<template><div class="admin-page"><el-card shadow="never" class="page-header"><div><h2>数据报表</h2><p>全校宿舍资源与服务运行情况</p></div><div><el-button @click="load">刷新</el-button><el-button type="primary" @click="exportCsv">导出 CSV</el-button></div></el-card><el-row :gutter="16" v-loading="loading"><el-col v-for="card in cards" :key="card.label" :span="6"><el-card shadow="never" class="metric"><span>{{card.label}}</span><strong>{{card.value}}</strong></el-card></el-col></el-row><el-row :gutter="16" class="section"><el-col :span="12"><el-card shadow="never"><h3>入住率</h3><el-progress :percentage="report.occupancyRate||0" :stroke-width="12"/><p>空床位 {{report.emptyBeds||0}} 张</p></el-card></el-col><el-col :span="12"><el-card shadow="never"><h3>报修完成率</h3><el-progress :percentage="report.repairCompletionRate||0" :stroke-width="12" status="success"/><p>已完成 {{report.completedRepairs||0}} / {{report.repairCount||0}} 单</p></el-card></el-col></el-row><el-card shadow="never" class="section"><h3>楼栋入住对比</h3><el-table :data="report.buildings||[]"><el-table-column prop="name" label="楼栋"/><el-table-column prop="roomCount" label="房间数"/><el-table-column prop="totalBeds" label="床位数"/><el-table-column prop="occupiedBeds" label="入住数"/><el-table-column label="入住率"><template #default="{row}"><el-progress :percentage="row.occupancyRate" :stroke-width="8"/></template></el-table-column></el-table></el-card></div></template>
<script setup>import { computed, onMounted, ref } from 'vue';import { getAdminReport } from '../../api/adminReport';const report=ref({buildings:[]}),loading=ref(false);const cards=computed(()=>[{label:'楼栋数',value:report.value.buildingCount||0},{label:'房间数',value:report.value.roomCount||0},{label:'入住床位',value:`${report.value.occupiedBeds||0}/${report.value.totalBeds||0}`},{label:'报修完成',value:`${report.value.completedRepairs||0}/${report.value.repairCount||0}`}]);const load=async()=>{loading.value=true;try{report.value=await getAdminReport()||{buildings:[]}}finally{loading.value=false}};const exportCsv=()=>{const rows=[['楼栋','房间数','床位数','入住数','入住率'],...(report.value.buildings||[]).map(x=>[x.name,x.roomCount,x.totalBeds,x.occupiedBeds,`${x.occupancyRate}%`])];const text='\uFEFF'+rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`宿舍运行报表-${new Date().toISOString().slice(0,10)}.csv`;link.click();URL.revokeObjectURL(url)};onMounted(load)</script>
<style scoped>.admin-page{max-width:1400px;margin:0 auto}.page-header{margin-bottom:20px}.page-header :deep(.el-card__body){display:flex;justify-content:space-between;align-items:center}.page-header h2{margin:0 0 6px}.page-header p{margin:0;color:var(--sub)}.metric{height:120px}.metric span,.metric strong{display:block}.metric span{color:var(--sub)}.metric strong{font-size:28px;margin-top:18px}.section{margin-top:16px}.section h3{margin-top:0}</style>
